#include "analysis.hpp"
#include <fstream>
#include <iostream>
void require(bool b,const char* s){if(!b)throw std::runtime_error(s);}
prep::Snapshot tube(){prep::Snapshot s;for(unsigned r=0;r<5;++r)for(unsigned j=0;j<6;++j){double a=j*6.283185307/6;s.positions.push_back({float(.002*std::cos(a)),float(.002*std::sin(a)),float(.025*r)});}for(unsigned r=0;r<4;++r)for(unsigned j=0;j<6;++j){unsigned a=r*6+j,b=r*6+(j+1)%6,c=a+6,d=b+6;s.faces.push_back({a,b,c});s.faces.push_back({b,d,c});s.materials.push_back(7);s.materials.push_back(7);}return s;}
int main(int argc,char** argv){try{std::atomic_bool cancel=false;std::atomic_int progress=0;auto s=tube();auto good=prep::analyze(s,{},cancel,progress);require(good.metadata["guides"].size()==1,"Tube guide detection");require(good.report["can_prepare"],"Tube admission");require(good.metadata["guides"][0]["parent"]==-1,"Ground root");auto second=prep::analyze(s,{},cancel,progress);require(good.metadata==second.metadata,"Deterministic analysis");
    auto rejects=[&](prep::Snapshot input){bool rejected=false;try{prep::analyze(input,{},cancel,progress);}catch(const std::exception&){rejected=true;}require(rejected,"Invalid input admitted");};
    auto bad=s;bad.faces[0][0]=99999;rejects(bad);bad=s;bad.positions[0][0]=std::numeric_limits<float>::quiet_NaN();rejects(bad);cancel=true;rejects(s);cancel=false;prep::Snapshot plane;plane.positions={{{0,0,0}},{{1,0,0}},{{0,1,0}}};plane.faces={{{0,1,2}}};plane.materials={0};rejects(plane);std::cout<<"PASS ordered tube, deterministic identity, topology bounds, nonfinite input, cancellation, unsupported topology\n";
    if(argc>=3){std::ifstream in(argv[1],std::ios::binary);unsigned h[4];in.read(reinterpret_cast<char*>(h),sizeof(h));require(h[0]==0x53544c32u&&h[1]<=1000000&&h[2]<=2000000,"Asset header");prep::Snapshot asset;asset.positions.resize(h[1]);asset.faces.resize(h[2]);asset.materials.resize(h[2]);in.read(reinterpret_cast<char*>(asset.positions.data()),h[1]*12);in.read(reinterpret_cast<char*>(asset.faces.data()),h[2]*12);in.read(reinterpret_cast<char*>(asset.materials.data()),h[2]*4);require(bool(in),"Asset payload");auto result=prep::analyze(asset,{},cancel,progress);std::cout<<result.report.dump(2)<<'\n';require(result.report["can_prepare"],"Lavender unresolved");require(result.metadata["guides"].size()==(argc==4?std::stoul(argv[3]):1290),"Lavender actual stems changed");std::ofstream out(argv[2]);out<<result.metadata.dump();}
    return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
